            </details>
        </div>

        <div class="border-t theme-transition border-part bg-black/5">
            <h3 class="px-4 pt-3 font-bold text-primary flex items-center">
                <i class="fa fa-map-signs mr-2"></i>
                剧情走向 (<span id="action-owner" class="text-main">...</span>)
            </h3>
            <div id="options-container" class="p-4 pt-2">
                <ul id="options-list" class="action-options-list space-y-2.5 text-sm"></ul>
            </div>
        </div>
