    <script>
        document.addEventListener('DOMContentLoaded', () => {
            const triggerQuickReply = (text) => {
                const cleanText = text.replace(/^\[.*?\]\s*/, '');
                if (!cleanText || ['…', '...'].includes(cleanText.trim()) || cleanText.trim().length === 0) return;

                const finalCommand = `/send ${cleanText}|/trigger`;
                if (typeof triggerSlash === 'function') {
                    try {
                        triggerSlash(finalCommand);
                    } catch (e) { console.error("SillyTavern triggerSlash failed:", e); }
                } else {
                    console.log('Woup Record [dev]:', finalCommand);
                }
            };

            const initThemeToggle = () => {
                const themeButtons = document.querySelectorAll('.theme-btn');
                const statusBlock = document.querySelector('.status-block');
                if (!statusBlock) return;
                const savedTheme = localStorage.getItem('xianxiaStatusTheme') || 'night';

                const switchToTheme = (theme) => {
                    statusBlock.classList.remove('day-mode', 'jade-mode', 'classic-mode');
                    if (theme !== 'night') {
                        statusBlock.classList.add(`${theme}-mode`);
                    }
                    themeButtons.forEach(btn => btn.classList.toggle('active', btn.dataset.theme === theme));
                    localStorage.setItem('xianxiaStatusTheme', theme);
                };

                themeButtons.forEach(button => button.addEventListener('click', () => switchToTheme(button.dataset.theme)));
                switchToTheme(savedTheme);
            };

            class StoryRenderer {
                constructor(dataSourceId) {
                    this.dataSourceId = dataSourceId;
                    this.elements = {};
                    try {
                        this.initElements();
                        this.loadAndParseYaml();
                        this.findRootNode();
                        this.renderAll();
                    } catch (error) { this.handleError(error); }
                }

                initElements() {
                    this.elements = {
                        title: document.getElementById('status-bar-title'),
                        time: document.getElementById('time-display'),
                        location: document.getElementById('location-display'),
                        characters: document.getElementById('characters-container'),
                        owner: document.getElementById('action-owner'),
                        options: document.getElementById('options-list')
                    };
                }

                loadAndParseYaml() {
                    const scriptEl = document.getElementById(this.dataSourceId);
                    if (!scriptEl) throw new Error('YAML数据源script未找到');
                    const rawYaml = scriptEl.textContent.trim();
                    if (!rawYaml) throw new Error('YAML内容为空');
                    this.yamlData = jsyaml.load(rawYaml);
                }

                findRootNode() {
                    const rootKeys = Object.keys(this.yamlData);
                    if (rootKeys.length === 0) throw new Error('YAML无根节点');
                    this.rootNodeKey = rootKeys[0];
                    this.rootData = this.yamlData[this.rootNodeKey];
                    if(this.elements.title) this.elements.title.textContent = this.rootNodeKey;
                }

                extractEmoji(text) {
                    if (typeof text !== 'string') return [null, text];
                    const emojiRegex = /[\u{1F600}-\u{1F64F}\u{1F300}-\u{1F5FF}\u{1F680}-\u{1F6FF}\u{2600}-\u{26FF}\u{2700}-\u{27BF}\u{1F900}-\u{1F9FF}☯-🙏]/u;
                    const match = text.match(emojiRegex);
                    const emoji = match ? match[0] : null;
                    const cleanText = emoji ? text.replace(emojiRegex, '').trim() : text;
                    return [emoji, cleanText];
                }

                findKeyByAlias(obj, aliases) {
                    return aliases.find(alias => obj && obj.hasOwnProperty(alias));
                }

                createFanchenMeter(valueString) {
                    const li = document.createElement('li');
                    li.className = 'flex flex-col sm:flex-row items-start sm:items-center gap-2';
                    const [emoji] = this.extractEmoji(valueString);
                    const match = valueString.match(/(\d+)\s*\/\s*(\d+)\s*\((.*?)\)/);

                    if (!match) {
                        li.innerHTML = `<span class="font-bold text-primary w-20 flex-shrink-0">${emoji || '☯️'} 凡心度:</span><span class="text-muted">${valueString}</span>`;
                        return li;
                    }

                    const current = parseInt(match[1]);
                    const max = parseInt(match[2]);
                    const stage = match[3];
                    const percentage = max > 0 ? (current / max) * 100 : 0;

                    li.innerHTML = `
                        <span class="font-bold text-primary w-20 flex-shrink-0">${emoji || '☯️'} 凡心度:</span>
                        <div class="fanchen-meter flex-grow theme-transition w-full">
                            <div class="fanchen-meter-fill theme-transition" style="width: ${percentage}%;"></div>
                            <div class="fanchen-meter-text theme-transition">${current} / ${max} (${stage})</div>
                        </div>`;
                    return li;
                }

                createCharacterCard(data) {
                    const card = document.createElement('div');
                    card.className = 'character-card p-4 theme-transition';

                    const nameKey = this.findKeyByAlias(data, ['名号', '名字', 'name']);
                    const fanchenKey = this.findKeyByAlias(data, ['凡心度', '凡心值']);
                    const [nameEmoji, nameText] = this.extractEmoji(data[nameKey] || '无名氏');

                    let titleIcon = nameEmoji || '👤';
                    if (nameKey === '仙尊') titleIcon = '👑';
                    if (nameKey === '弟子') titleIcon = '🌸';

                    card.innerHTML = `<h3 class="font-bold text-lg mb-3 pb-2 border-b border-part flex items-center theme-transition text-main">${titleIcon} ${nameText}</h3>`;

                    const list = document.createElement('ul');
                    list.className = 'space-y-3 text-sm';
                    card.appendChild(list);

                    Object.keys(data).forEach(key => {
                        if (key === nameKey) return;

                        if (key === fanchenKey) {
                            list.appendChild(this.createFanchenMeter(data[key]));
                        } else {
                            const [valEmoji, valText] = this.extractEmoji(data[key]);
                            const li = document.createElement('li');
                            li.className = 'flex items-start';
                            li.innerHTML = `<span class="font-bold text-primary w-20 flex-shrink-0">${valEmoji || '📜'} ${key}:</span><span class="text-muted break-words">${valText}</span>`;
                            list.appendChild(li);
                        }
                    });

                    return card;
                }

                renderAll() {
                    const { time, location, characters, owner, options } = this.elements;

                    const timeKey = this.findKeyByAlias(this.rootData, ['天时', 'time']);
                    const locKey = this.findKeyByAlias(this.rootData, ['地利', 'location']);

                    const updateField = (el, key, defaultEmoji) => {
                        if (key && this.rootData[key]) {
                            const [emoji, text] = this.extractEmoji(this.rootData[key]);
                            el.textContent = text;
                            el.previousElementSibling.textContent = emoji || defaultEmoji;
                        }
                    };
                    updateField(time, timeKey, '🕰️');
                    updateField(location, locKey, '📍');

                    const charsKey = this.findKeyByAlias(this.rootData, ['诸人情状', 'users']);
                    const charList = charsKey ? this.rootData[charsKey] : [];
                    characters.innerHTML = '';
                    if (charList.length === 0) {
                        characters.innerHTML = `<p class="text-muted text-center py-4 col-span-full">此界暂无人迹。</p>`;
                    } else {
                        charList.forEach(charItem => {
                           const charDataKey = Object.keys(charItem)[0];
                           const charData = charItem[charDataKey];
                           if(charData) characters.appendChild(this.createCharacterCard(charData));
                        });
                    }

                    const actionsKey = this.findKeyByAlias(this.rootData, ['剧情走向', 'actions']);
                    const actionData = actionsKey ? this.rootData[actionsKey] : {};
                    const ownerKey = this.findKeyByAlias(actionData, ['主角', 'owner']);
                    const optsKey = this.findKeyByAlias(actionData, ['选项', 'options']);
                    const optsList = optsKey ? actionData[optsKey] : [];

                    owner.textContent = ownerKey ? this.extractEmoji(actionData[ownerKey])[1] : '...';
                    options.innerHTML = '';
                    if (optsList.length === 0) {
                        options.innerHTML = `<li class="text-muted italic">前路漫漫，尚无定数。</li>`;
                    } else {
                        optsList.forEach(opt => {
                            const li = document.createElement('li');
                            const tagMatch = opt.match(/^(\[.*?\])/);
                            const text = tagMatch ? opt.substring(tagMatch[0].length).trim() : opt;
                            const tagHtml = tagMatch ? `<span class="option-tag text-xs font-bold px-2 py-0.5 rounded-full border theme-transition">${tagMatch[1]}</span>` : '';

                            li.innerHTML = `${tagHtml}<span class="option-text">${text}</span>`;
                            li.onclick = () => triggerQuickReply(opt);
                            options.appendChild(li);
                        });
                    }
                }

                handleError(error) {
                    console.error('江湖纪要渲染错误:', error);
                    const container = document.querySelector('.status-block');
                    if(container) container.innerHTML = `<div class="text-red-400 bg-red-900/50 border border-red-700 p-4 rounded-md m-4"><strong>[记录出错]</strong><p class="mt-2 text-red-300">卷宗残缺，天机有误。</p><p class="text-xs text-red-500 mt-1">${error.message}</p></div>`;
                }
            }

            initThemeToggle();
            new StoryRenderer('yaml-data-source');
        });
    </script>
</body>
</html>
